export function M(key) {
  const row = S[key];
  if (!row) return key;
  const lang = getLang();
  return row[lang] || row[String(lang).split('-')[0]] || row.en || row.bg || key;
}
// С параметри {0}, {1}…
export function MF(key, ...vals) { let s = M(key); vals.forEach((v, i) => { s = s.replace(new RegExp('\\{' + i + '\\}', 'g'), String(v)); }); return s; }
